		user.isAdministrator(uid),
		helpers.isAllowedTo(isArray ? privilege : [privilege], uid, 0),
	]);
	return isArray ?
		isUserAllowedTo.map(allowed => isAdministrator || allowed) :
		isAdministrator || isUserAllowedTo[0];
};

